mapper.select:
SELECT link.corpus_id AS documentId, tag.id, tag.name, tag.level FROM tech_english_corpus_tag AS link INNER JOIN knowledge_tag AS tag ON tag.id = link.tag_id AND tag.deleted = 0 WHERE link.deleted = 0 AND link.corpus_id IN
#{corpusId}
ORDER BY tag.level ASC, tag.sort_order ASC, tag.id ASC
